using System;
using System.Collections;

// PROGRAM: Menginspeksi Environment Variables & Saluran Output
Console.WriteLine("=== DIAGNOSTIK TERMINAL & ENVIRONMENT ===");
Console.WriteLine($"Machine Name: {Environment.MachineName}");
Console.WriteLine($"User Domain: {Environment.UserDomainName}");
Console.WriteLine($"Current Directory: {Environment.CurrentDirectory}");

// Menampilkan beberapa direktori yang terdaftar di variabel PATH
string? pathVar = Environment.GetEnvironmentVariable("PATH");
if (!string.IsNullOrEmpty(pathVar))
{
    char separator = Path.PathSeparator; // Titik koma (;) di Windows, titik dua (:) di Linux
    string[] paths = pathVar.Split(separator, StringSplitOptions.RemoveEmptyEntries);

    Console.WriteLine($"\nTotal direktori di PATH: {paths.Length}");
    Console.WriteLine("3 Direktori pertama di PATH:");
    for (int i = 0; i < Math.Min(3, paths.Length); i++)
    {
        Console.WriteLine($" [{i + 1}] {paths[i]}");
    }
}

// Menulis ke stderr secara terpisah dari stdout
Console.Error.WriteLine("[DIAGNOSTIC NOTICE] Pesan ini dikirim ke STDERR!");

