using System;

public class PathResolver
{
    public static string? ResolveBinary(string pathVariable, string[] existingFiles, string targetBinary)
    {
        if (string.IsNullOrWhiteSpace(pathVariable) || existingFiles == null || string.IsNullOrWhiteSpace(targetBinary))
            return null;

        var dirs = pathVariable.Split(';', StringSplitOptions.RemoveEmptyEntries);
        var fileSet = new System.Collections.Generic.HashSet<string>(existingFiles, StringComparer.OrdinalIgnoreCase);

        foreach (var rawDir in dirs)
        {
            var dir = rawDir.Trim();
            string candidate = $"{dir}/{targetBinary}";
            if (fileSet.Contains(candidate))
            {
                return candidate;
            }
        }

        return null;
    }

    public static void Main()
    {
        string path = "C:/Windows;C:/Program Files/dotnet;C:/Tools";
        string[] files = { "C:/Windows/notepad.exe", "C:/Program Files/dotnet/dotnet.exe" };
        Console.WriteLine(ResolveBinary(path, files, "dotnet.exe"));
    }
}
